package com.bank.cheque.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Maximizes the number of allowed-length pieces that exactly form the total length.
public class ChequeStripService {
    private static final Logger log = Logger.getLogger(ChequeStripService.class.getName());

    public int maxPieces(int[] lengths, int total) {
        int[] dp = new int[total + 1];
        Arrays.fill(dp, -1);                        // -1 means unreachable
        dp[0] = 0;                                  // length 0 needs 0 pieces
        for (int len = 1; len <= total; len++) {
            for (int cut : lengths) {
                if (cut <= len && dp[len - cut] != -1) {   // remainder must be reachable
                    dp[len] = Math.max(dp[len], 1 + dp[len - cut]);
                }
            }
        }
        final int r = dp[total];
        log.info(() -> "Max pieces for length " + total + " = " + r);
        return dp[total];
    }
}
