package com.bank.cheque;

import com.bank.cheque.service.ChequeStripService;
import java.util.logging.Logger;

public class ChequeStripApplication {
    private static final Logger log = Logger.getLogger(ChequeStripApplication.class.getName());

    public static void main(String[] args) {
        ChequeStripService service = new ChequeStripService();
        int[] approved = {2, 3, 5};     // approved segment lengths
        int total = 7;                   // cheque strip length
        int pieces = service.maxPieces(approved, total);
        log.info("Maximum cheque segments from length " + total + ": " + pieces);
    }
}
